eigen zorgen over relaties, familie en veranderingen in hun leven. Wanneer ook een onbekende man bij de school verschijnt, krijgen hun persoonlijke vragen een onheilspellende achtergrond. De roman keert terug naar Madeline, Celeste, Jane, Renata en Bonnie en de wereld die zij met elkaar delen.","work_id":978100119,"evidence":[{"url":"https://metadata.isbn.nl/2117691/grote-kleine-waarheid.html","fact":"Paperback ISBN 9789400520486 verschijningsdatum 13/10/2026 NUR 302 Vertaalde literaire roman, novelle imprint A.W. Bruna Uitgevers uitgever Bruna Uitgevers B.V., A.W. taal Engels","sha256":"0e4071ab52a1f05aeb8814070f79dde19f960b647ff2f66e9e204b5ab18805ee","checkedAt":"2026-11-01T20:43:40.692Z","sourceAuthors":"Liane Moriarty"},{"url":"https://metadata.isbn.nl/2117691/grote-kleine-waarheid.html","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content.","checkedAt":"2026-11-01T21:37:32Z"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/2117691/grote-kleine-waarheid.html","reviewed_at":"2026-11-01T21:37:32+00:00","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl007-reviewed-batch-09-20261101","review_status":"approved","bound_author_id":978300061},"before_row":null},{"key":{"id":978100120},"seq":13,"relation":"works","after_row":{"id":978100120,"title":"De vrouw van mijn echtgenoot","cover_id":null,"author_id":978300062,"work_type":null,"source_type":"lumiscore_native","open_library_id":null,"first_publish_year":null,"native_identity_key":"nl-reviewed-isbn:9789049211363"},"before_row":null},{"key":{"id":978200178},"seq":14,"relation":"editions","after_row":{"id":978200178,"title":"De vrouw van mijn echtgenoot","isbn_10":null,"isbn_13":"9789049211363","work_id":978100120,"cover_id":null,"language":"nld","publisher":"Boekerij","publish_date":null,"open_library_edition_id":null},