 te herkennen. Terwijl anderen twijfelen aan haar waarneming, wil Eva weten wie deze man is en wat er van haar eerdere leven werkelijk klopt.","work_id":978100120,"evidence":[{"url":"https://metadata.isbn.nl/2076738/de-vrouw-van-mijn-echtgenoot.html","fact":"Paperback ISBN 9789049211363 verschijningsdatum 18/08/2026 NUR 330 Spannende boeken algemeen imprint Boekerij uitgever Meulenhoff Boekerij B.V. taal Engels","sha256":"782a9f9147978e1e241ba945f8c836b5c8a232e3329c55d561616d3c4b56c7e7","checkedAt":"2026-11-01T20:43:43.177Z","sourceAuthors":"Carla Kovach"},{"url":"https://metadata.isbn.nl/2076738/de-vrouw-van-mijn-echtgenoot.html","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content.","checkedAt":"2026-11-01T21:37:32Z"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/2076738/de-vrouw-van-mijn-echtgenoot.html","reviewed_at":"2026-11-01T21:37:32+00:00","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl007-reviewed-batch-09-20261101","review_status":"approved","bound_author_id":978300062},"before_row":null},{"key":{"id":978100121},"seq":17,"relation":"works","after_row":{"id":978100121,"title":"Montmartre – Traum und Schicksal","cover_id":null,"author_id":978300063,"work_type":null,"source_type":"lumiscore_native","open_library_id":null,"first_publish_year":null,"native_identity_key":"nl-reviewed-isbn:9789049211356"},"before_row":null},{"key":{"id":978200179},"seq":18,"relation":"editions","after_row":{"id":978200179,"title":"Een toekomst in Montmartre","isbn_10":null,"isbn_13":"9789049211356","work_id":978100121,"cover_id":null,"language":"nld","publisher":"Boekerij","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":978200179},"seq":19,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":978100121,"ev