en voor haar eigen ambities in de schilderkunst. Het slotdeel van het tweeluik volgt twee vrouwen die in dezelfde stad hun toekomst zoeken, maar daarbij elk andere beperkingen ontmoeten.","work_id":978100121,"evidence":[{"url":"https://metadata.isbn.nl/2122813/een-toekomst-in-montmartre.html","fact":"Paperback ISBN 9789049211356 verschijningsdatum 13/10/2026 NUR 302 Vertaalde literaire roman, novelle imprint Boekerij uitgever Meulenhoff Boekerij B.V. taal Duits","sha256":"a7a2429f363eaf02b40501a896098e34c0a2e965089d8e74d047bb77df0834e4","checkedAt":"2026-11-01T20:43:45.384Z","sourceAuthors":"Marie Lacrosse"},{"url":"https://metadata.isbn.nl/2122813/een-toekomst-in-montmartre.html","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content.","checkedAt":"2026-11-01T21:37:32Z"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/2122813/een-toekomst-in-montmartre.html","reviewed_at":"2026-11-01T21:37:32+00:00","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl007-reviewed-batch-09-20261101","review_status":"approved","bound_author_id":978300063},"before_row":null},{"key":{"id":978100122},"seq":21,"relation":"works","after_row":{"id":978100122,"title":"Het C.R.U.I.S.E. complot","cover_id":null,"author_id":978300064,"work_type":null,"source_type":"lumiscore_native","open_library_id":null,"first_publish_year":null,"native_identity_key":"nl-reviewed-isbn:9789464106121"},"before_row":null},{"key":{"id":978200180},"seq":22,"relation":"editions","after_row":{"id":978200180,"title":"Het C.R.U.I.S.E. complot","isbn_10":null,"isbn_13":"9789464106121","work_id":978100122,"cover_id":null,"language":"nld","publisher":"Horizon","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":978200180},"seq":23,"relation":"catalog_edition_metadata","after_row":{"forma