before":null,"after":{"work_id":978100118,"language":"nl","bound_author_id":978300060,"text":"Op een ochtend blijken de rekeningen van klanten van het Gemeentekrediet te zijn leeggehaald. Zelfs de hoofdcommissaris is zijn geld kwijt. De bankdirecteur is verdwenen en lijkt een centrale rol in de fraude te spelen. Van In en Versavel moeten uitzoeken hoe de operatie kon plaatsvinden zonder duidelijke sporen achter te laten. Hun onderzoek voert door een wereld waarin financiële kennis en verzwegen belangen nauw samenhangen.","source_type":"official_catalog","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/2117392/bankgeheim.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-09-20261101","evidence":[{"url":"https://metadata.isbn.nl/2117392/bankgeheim.html","sha256":"2f1dc8ab672df0d543bb78ecc5553843f7d949ac5a3908bade61b0d6fd8e3a54","checkedAt":"2026-11-01T20:43:38.254Z","fact":"Paperback ISBN 9789022343135 verschijningsdatum 22/09/2026 NUR 330 Spannende boeken algemeen imprint Manteau uitgever Standaard Uitgeverij - Algemeen taal Nederlands","sourceAuthors":"Jonas Boets"},{"url":"https://metadata.isbn.nl/2117392/bankgeheim.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"works","ref":"work:new-grotekleinewaarheid","key":{"id":978100119},"before":null,"after":{"id":978100119,"title":"Big Little Truths","cover_id":null,"author_id":978300061,"work_type":null,"source_type":"lumiscore_native","open_library_id":null,"first_publish_year":null,"native_identity_key":"nl-reviewed-isbn:9789400520486"}},{"relation":"editions","ref":"edition:9789400520486","key":{"id":978200177},"before":null,"after":{"id":978200177,"title":"Grote kleine waarheid","isbn_10":null,"isbn_13":"9789400520486",