t Timon een boodschap in een fles. Zijn nieuwsgierigheid naar de afzender brengt hem op een ongewoon cruiseschip. Wat als een zoektocht begint, wordt een avontuur waarin de reis niet meer volgens de verwachtingen van een gewone vakantieganger verloopt. Het verhaal gebruikt een fictieve Timon Verbeeck als hoofdpersoon, die tussen nieuwe ontmoetingen en eigenaardige gebeurtenissen probeert te ontdekken waar hij in terechtgekomen is.","source_type":"official_catalog","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/2128607/het-c-r-u-i-s-e-complot.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-09-20261101","evidence":[{"url":"https://metadata.isbn.nl/2128607/het-c-r-u-i-s-e-complot.html","sha256":"843ab5870c80dddf51840cf09425acf03875186b1e5035fe54d2aea1600ba118","checkedAt":"2026-11-01T20:43:47.584Z","fact":"Hardback ISBN 9789464106121 verschijningsdatum 24/09/2026 NUR 283 Fictie 10-12 jaar 282 Fictie 7-9 jaar imprint Horizon uitgever Overamstel Uitgevers taal Nederlands","sourceAuthors":"Timon Verbeeck"},{"url":"https://metadata.isbn.nl/2128607/het-c-r-u-i-s-e-complot.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"works","ref":"work:new-indepuree","key":{"id":978100123},"before":null,"after":{"id":978100123,"title":"In de puree","cover_id":null,"author_id":978300065,"work_type":null,"source_type":"lumiscore_native","open_library_id":null,"first_publish_year":null,"native_identity_key":"nl-reviewed-isbn:9789083624440"}},{"relation":"editions","ref":"edition:9789083624440","key":{"id":978200181},"before":null,"after":{"id":978200181,"title":"In de puree","isbn_10":null,"isbn_13":"9789083624440","work_id":978100123,"cover_id":null,"language":"nld","publisher":"Höngry","